private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    byte octet = bb.get(i++);
    if (octet >= 0 && octet <= 127) {
        sb.append((char) octet);
        return i;
    } else if (octet == 192) { // UTF-8 continuations
        if (bb.remaining() < 1) throw new IllegalArgumentException("Incomplete UTF-8 control byte");
        byte continuation1 = bb.get(i++);
        if (!isContinuationByte(continuation1)) throw new IllegalArgumentException("Invalid UTF-8 continuation byte");

        int value = ((octet - 192) << 6) | (continuation1 & 63);
        sb.append((char) value);
        return i;
    } else if (octet >= 224) { // UTF-8 sequences
        if (bb.remaining() < 2) throw new IllegalArgumentException("Incomplete UTF-8 sequence");
        byte continuation1 = bb.get(i++);
        byte continuation2 = bb.get(i++);
        if (!isContinuationByte(continuation1) || !isContinuationByte(continuation2)) throw new IllegalArgumentException("Invalid UTF-8 continuation byte");

        int value = ((octet - 224) << 12) | ((continuation1 & 63) << 6) | (continuation2 & 63);
        sb.append((char) value);
        return i;
    } else if (octet >= 240) { // UTF-8 pieces
        if (bb.remaining() < 3) throw new IllegalArgumentException("Incomplete UTF-8 piece");
        byte continuation1 = bb.get(i++);
        byte continuation2 = bb.get(i++);
        byte continuation3 = bb.get(i++);
        if (!isContinuationByte(continuation1) || !isContinuationByte(continuation2) || !isContinuationByte(continuation3)) throw new IllegalArgumentException("Invalid UTF-8 continuation byte");

        int value = ((octet - 240) << 18) | ((continuation1 & 63) << 12) | ((continuation2 & 63) << 6) | (continuation3 & 63);
        sb.append((char) value);
        return i;
    } else {
        throw new IllegalArgumentException("Invalid UTF-8 leading byte");
    }
}

