private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        Exception e = new IllegalArgumentException("Cannot perform rotation on a null or left child node.");
        throw e;
    }

    TreeNode<T> rightChild = node.left;
    node.left = rightChild.right;
    rightChild.right = node;
    node = rightChild;
    return node;
}

