public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Check if genericType is parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Get the actual type arguments of genericType
    Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();

    // Check if targetType matches the first type argument of the genericType
    if (!targetType.equals(typeArguments[0])) {
        return null;
    }

    // Resolve the common superclass of targetType and the first type argument
    Type superclass = typeArguments[0].getCommonSupertype(targetType);

    // Convert the superclass type to Class[]
    Class<?>[] resolvedArguments = new Class<?>[typeArguments.length - 1];
    for (int i = 1; i < typeArguments.length; i++) {
        resolvedArguments[i - 1] = (Class<?>) typeArguments[i];
    }

    return resolvedArguments;
}

