    }

    // Check if the bucket is already in the data structure
    if (dataStructure.containsKey(bucket.getId())) {
        throw new IllegalArgumentException("Bucket is already in the data structure");
    }

    // Insert the bucket before the specified bucket
    dataStructure.put(bucket.getId(), bucket);

    // Optionally, update the order of buckets in the data structure
    List<Bucket> bucketList = new ArrayList<>(dataStructure.values());
    bucketList.add(0, bucket);

    // Update the data structure with the reordered buckets
    dataStructure.clear();
    dataStructure.putAll(bucketList);
}

