public long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket <= 0 || dayStep <= 0) {
        throw new IllegalArgumentException("Time bucket and day step must be positive integers.");
    }

    long startYear = timeBucket / (10000 * dayStep);
    long startMonth = (timeBucket % (10000 * dayStep)) / 10000;
    long startDay = timeBucket % 10000;

    long compressedYear = startYear;
    long compressedMonth;
    long compressedDay = startDay;

    if (startYear % dayStep == 0) {
        compressedYear = startYear / dayStep;
    } else {
        compressedYear = startYear - (startYear % dayStep) / dayStep + 1;
    }

    if (startMonth % dayStep == 0) {
        compressedMonth = startMonth / dayStep;
    } else {
        compressedMonth = startMonth - (startMonth % dayStep) / dayStep + 1;
    }

    if (startDay % dayStep == 0) {
        compressedDay = startDay / dayStep;
    } else {
        compressedDay = startDay - (startDay % dayStep) / dayStep + 1;
    }

    return (compressedYear * (10000 * dayStep) + compressedMonth * (10000) + compressedDay);
}

public static int computeUTF8Size(final CharSequence str, int index, int len) throws IllegalArgumentException {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    if (index < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Index and length out of bounds");
    }
    int size = 0;
    int i = index;
    while (i < index + len) {
        int b = str.charAt(i++);
        if ((b & 0xF0) == 0xF0) {
            b = str.charAt(i++) & 0x0F;
            b = str.charAt(i++) & 0x0F;
            size += 3;
        } else if ((b & 0xE0) == 0xE0) {
            b = str.charAt(i++) & 0x0F;
            b = str.charAt(i++) & 0x0F;
            size += 2;
        } else if ((b & 0xC0) == 0xC0) {
            b = str.charAt(i++) & 0x0F;
            size += 1;
        } else {
            break;
        }
    }
    return size;
}

