    // Check for invalid inputs
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (start < 0 || end > str.length()) {
        throw new IllegalArgumentException("Start and end indices are out of bounds");
    }

    // Ensure start is less than or equal to end
    if (start > end) {
        int temp = start;
        start = end;
        end = temp;
    }

    // Extract the substring
    if (str.length() - end >= 0) {
        return str.substring(start, end);
    } else {
        throw new IllegalArgumentException("End index is beyond the length of the string");
    }
}

