public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    byte[] utf8Bytes = null;
    try {
        utf8Bytes = str.toString().getBytes("UTF-8");
    } catch (UnsupportedEncodingException e) {
        throw new RuntimeException("UTF-8 encoding not supported, Please ensure JDK 8 or later", e);
    }

    if (utf8Bytes == null || utf8Bytes.length == 0) {
        return lb;
    }

    int numBytesWritten;
    ByteBuffer buffer = session.allocate(utf8Bytes.length);
    buffer.put(utf8Bytes);
    buffer.flip();
    numBytesWritten = session.write(buffer);

    if (numBytesWritten != utf8Bytes.length) {
        throw new RuntimeException("Unable to write all bytes to the linked buffer");
    }

