public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    String path = u.getPath();
    boolean absolute = u.isAbsolute();

    if (absolute) {
        path = path.substring(1);
    }

    if (!decode) {
        return List.of(new PathSegmentImpl(path));
    }

    try {
        for (String segment : path.split("/")) {
            segments.add(new PathSegmentImpl(decode ? URLDecoder.decode(segment, StandardCharsets.UTF_8) : segment));
        }
    } catch (UnsupportedEncodingException e) {
        // Handle the exception appropriately
    }

    return segments;
}

