        throw new IllegalArgumentException("Box cannot be null");
    }

    double width = box.getWidth();
    if (width <= 0) {
        throw new IllegalArgumentException("Box width must be positive");
    }

    double leftWidth = width / 2;
    Box2D leftBox = new Box2D(leftWidth, box.getMinY(), box.getMaxX(), box.getUpperY());
