public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be a positive integer");
    }

    if (desiredCapacity < 1000) {
        if (desiredCapacity % 2 == 0) {
            return desiredCapacity + 1;
        }
        return nextPrime(desiredCapacity + 2);
    }

    int primePotential = desiredCapacity * 1.11;

    if (primePotential <= desiredCapacity) {
        return nextPrime((int) (primePotential + 1));
    }

    int max = (int) Math.sqrt(primePotential);
    for (int index = 2; index <= max; index++) {
        if (primePotential % index == 0) {
            return nextPrime((int) (primePotential + 1));
        }
    }

    return primePotential;
}

