public static String unescapeJava(String str) throws Exception {
    if (str == null) return null; // Check if the input string is null

    StringBuilder result = new StringBuilder(); // Initialize a StringBuilder to build the result
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i); // Get the current character

        // Check if the character before the current character is a backslash
        if (i > 0) {
            char prevChar = str.charAt(i - 1);
            if (prevChar == '\\') {
                // Replace the backslash with the non-escaped character
                result.append(c);
            } else {
                // Escape the character by appending the backslash followed by the character
                result.append('\\');
                result.append(c);
            }
        } else {
            // Escape the first character directly
            result.append('\\');
            result.append(c);
        }
    }

    return result.toString();
}

