    }

    byte firstByte = this.dataBuffer[offset];
    byte secondByte = this.dataBuffer[offset + 1];

    // Combine the two bytes into an integer using big-endian conversion (x<<8)+y
    int value = (firstByte << 8) | secondByte;

    // Ensure the value fits within a short range (-32768 to 32767)
    if (value < Short.MIN_VALUE || value > Short.MAX_VALUE) {
        throw new IllegalArgumentException("Value out of the short range"); // Handle invalid inputs
    }

    // Convert the integer to a short and return
    return (short) value;
}

