public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Both tour and graph cannot be null");
    }

    Set<Edge<V, E>> transformedTour = new HashSet<>();
    for (E edge : tour) {
        int src = edge.getSource().toInt();
        int dst = edge.getDestination().toInt();
        transformedTour.add(new Edge<>(graph.getNode(src), graph.getNode(dst)));
    }

    return new GraphPath<>(transformedTour);
}

