private void reload(
    List<Set<Integer>> bucketsByLabel,
    List<Integer> labels,
    int minLabel
) {
    if (minLabel < 0) {
        throw new IllegalArgumentException("Label must be non-negative");
    }

    if (minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Label cannot be greater than or equal to the number of buckets");
    }

    Set<Integer> bucketToMove = bucketsByLabel.remove(minLabel);
    bucketsByLabel.add(0, bucketToMove);

    for (int i = 0; i < labels.size(); i++) {
        int label = labels.get(i);
        if (label == minLabel) {
            labels.set(i, 0);
        }
    }
}

