            throw new IllegalArgumentException("SegmentSnapshot must be a List");
        }
        if (!searchParams.getClass().isInstance(SearchParams.class)) {
            throw new IllegalArgumentException("SearchParams must be an instance of SearchParams");
        }
        if (segmentSnapshot.getClass().isInstance(Stream.class)) {
            segmentSnapshot = segmentSnapshot.collect(Collectors.toList());
        }

        List<SequenceRange> sequenceRanges = new ArrayList<>();
        int endIndex = segmentSnapshot.size() <= searchParams.startIndex ? segmentSnapshot.size() : searchParams.startIndex + searchParams.endIndex;
        for (int i = searchParams.startIndex; i < endIndex; i++) {
            sequenceRanges.add(new SequenceRange(i, i + searchParams.endIndex > segmentSnapshot.size() ? segmentSnapshot.size() : searchParams.endIndex - i));
        }

        return sequenceRanges;
    }

