public static String trimLeadingCharacter(String str, char leadingCharacter) {
    // Check if the input string is empty
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    // Initialize an index to track the position of the first character that is not the leading character
    int index = 0;

    // Iterate through the input string
    while (index < str.length() && str.charAt(index) == leadingCharacter) {
        // Move the index forward to the next character
        index++;
    }

    // If the entire string is composed of the leading character, return an empty string
    if (index == str.length()) {
        return "";
    }

    // Return the substring of the input string starting from the found index
    return str.substring(index);
}

