    // Check if the array is null or does not have enough elements to reverse
    if (arr == null || arr.length < Math.abs(to - from) + 1) {
        throw new IllegalArgumentException("Invalid array provided or range too large.");
    }

    // Perform the reversal of the array within the specified range
    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

