private List<Integer> computeLowerBounds(List<K> keys){
    // Initialize a list to store the computed lower bounds
    List<Integer> lowerBounds = new ArrayList<>();

    // Check if the list of keys is empty
    if (keys == null || keys.isEmpty()) {
        return lowerBounds;  // Return an empty list if the input is invalid
    }

    // Initialize variables to keep track of the current lower bound and the last visited key
    int currentLowerBound = Integer.MAX_VALUE;
    K lastVisitedKey = null;

    // Iterate through the list of keys
    for (K key : keys) {
        // Check if the current key is not the same as the last visited key
        if (key != lastVisitedKey) {
            // Adjust the current lower bound if necessary
            if (key.compareTo(lastVisitedKey) < 0) {
                currentLowerBound = key.hashCode();
            }
            // Update the last visited key
            lastVisitedKey = key;
        }
        // Add the computed lower bound to the result list
        lowerBounds.add(currentLowerBound);
    }

    // Return the list of computed lower bounds
    return lowerBounds;
}

