public static String applyRelativePath(String path, String relativePath) 
{
    // validate input parameters
    if (path == null || relativePath == null) 
    {
        throw new IllegalArgumentException("Both path and relativePath cannot be null.");
    }

    // trim white spaces from both the start and end
    path = path.trim();
    relativePath = relativePath.trim();

    // if relativePath is empty or only contains white space, return path as it is
    if (relativePath.isEmpty() || relativePath.isBlank()) 
    {
        return path;
    }

    // replace all occurrences of '.' in relativePath with file separator '/'
    relativePath = relativePath.replace('.', '/');

    // normalize relativePath by removing consecutive slashes and prepending them with path separator '/'
    relativePath = relativePath.replaceAll("/{2,}", "/");
    relativePath = "/" + path + relativePath;

    return relativePath;
}

