public int readTag() throws IOException {
    // Prefetch value to read
    byte fieldNumberByte = val[++cursor];
    if ((fieldNumberByte & 128) == 0) {
        return (int) fieldNumberByte;
    } else {
        byte highByte = val[++cursor];
        int fieldNumber = ((fieldNumberByte & 127) << 7) | (int) highByte;
        // Check for valid tag
        if (fieldNumber >= kMinTagNumber && fieldNumber <= kMaxTagNumber) {
            return fieldNumber;
        } else {
            throw new IOException("Invalid tag number: " + fieldNumber);
        }
    }
}

